def windowLowerMedians(nums, k):
    vals = sorted(set(nums))
    rank = {v: i + 1 for i, v in enumerate(vals)}
    m = len(vals)
    tree = [0] * (m + 1)
    top = 1
    while top * 2 <= m:
        top *= 2

    def update(i, delta):
        while i <= m:
            tree[i] += delta
            i += i & -i

    def kth(t):
        pos = 0
        step = top
        while step:
            nxt = pos + step
            if nxt <= m and tree[nxt] < t:
                pos = nxt
                t -= tree[nxt]
            step >>= 1
        return pos + 1

    target = (k - 1) // 2 + 1
    res = []
    for i, x in enumerate(nums):
        update(rank[x], 1)
        if i >= k:
            update(rank[nums[i - k]], -1)
        if i >= k - 1:
            res.append(vals[kth(target) - 1])
    return res
